// HIGH FRONTIER: AD ASTRA - star systems built from the Sol board (AA-B7a).
//
// Every system is assembled from body clusters CUT OUT OF THE REAL HF SOL BOARD
// (sol-templates.js, generated by extract-sol-templates.py), at Sol's own scale,
// so a system reads exactly like Sol: burn ladders, Lagrange points, Hohmann
// transfers, radiation hazards, curved routes, multi-site bodies and moons.
//   gas giant / brown dwarf / white dwarf  <- the Jupiter cluster: you come into
//       the giant's well first, then branch out to its moons
//   habitable-zone world                   <- the Mars cluster (3 regions + 2 small moons)
//   inner rocky world                      <- the Mercury cluster (2 regions)
//   asteroid belt                          <- the Ceres neighbourhood
// The clusters are wired into ONE gravity well by Sol-style transfer chains:
// you arrive at the system's edge and each band further in costs more burns.
import { SOL_TEMPLATES } from './sol-templates.js';

export const SYSTEM_LAYOUT = 4;
const SPEC = ['C', 'S', 'M', 'V'];
const CLASS_HYD = { Garden: [6, 9], Habitable: [4, 7], Marginal: [2, 5], Hostile: [0, 3] };
const STEP_OF = { Marginal: 2, Habitable: 3, Garden: 4, Hostile: 0 };
const ROMAN = ['I', 'II', 'III', 'IV', 'V', 'VI'];
// Region descriptors replace Sol's place names (Loki Patera etc.)
const GALILEAN = {
  io: ['lava plains', 'sulfur flats'],
  europa: ['subsurface ocean', 'chaos terrain'],
  ganymede: ['grooved terrain', 'bright facula'],
  callisto: ['impact basin', 'ice spires'],
};
const MARS_REGIONS = ['north pole', 'buried glaciers', 'lava-tube caves'];
const MERCURY_REGIONS = ['north pole', 'great scarp'];

// Where each cluster sits in the 1400x900 board world, around a star at (700, 450).
const PLACE = { star: [700, 450], high: [760, 28], gas0: [330, 250], gas1: [1150, 640], belt: [985, 255], hz: [520, 610], rock: [845, 470] };

export function buildSystem({ star, chits, rint, worldName, keep }) {
  const short = star.name.split(' ')[0].replace(/'s$/, '');
  const nodes = [], edges = [], sites = [], display = [];
  const byId = {};
  const addNode = (n) => { nodes.push(n); byId[n.id] = n; return n.id; };
  const link = (a, b) => { if (a && b && a !== b) edges.push([a, b]); };

  // place a Sol cluster: returns { ids, ports, siteNodes }
  const place = (tplKey, prefix, [cx, cy], scale = 1) => {
    const t = SOL_TEMPLATES[tplKey];
    const ids = t.nodes.map((n, i) => addNode({ id: `${prefix}${i}`, kind: n.t, x: Math.round((cx + n.x * scale) * 10) / 10, y: Math.round((cy + n.y * scale) * 10) / 10, solName: n.n || null, land: n.land || null }));
    for (const [a, b] of t.edges) link(ids[a], ids[b]);
    return { ids, ports: t.ports.map((i) => ids[i]), t };
  };
  // a Sol-style transfer chain between two nodes: Hohmann nodes at the ends,
  // magenta burn pads along the way, hidden waypoints bending it into an arc
  const chain = (fromId, toId, burns, tag, bend = 0.18) => {
    const A = byId[fromId], B = byId[toId];
    const dx = B.x - A.x, dy = B.y - A.y, len = Math.hypot(dx, dy);
    const n = Math.max(4 + burns * 2, Math.round(len / 34));
    const cx = (A.x + B.x) / 2 - dy * bend, cy = (A.y + B.y) / 2 + dx * bend;
    const kinds = Array(n - 1).fill('decorative');
    kinds[0] = 'hohmann'; kinds[n - 2] = 'hohmann';
    for (let k = 0; k < burns; k++) kinds[Math.min(n - 3, Math.max(1, Math.round((k + 1) * (n - 1) / (burns + 1))))] = 'burn';
    let prev = fromId;
    for (let i = 1; i < n; i++) {
      const s = i / n;
      const x = (1 - s) * (1 - s) * A.x + 2 * (1 - s) * s * cx + s * s * B.x;
      const y = (1 - s) * (1 - s) * A.y + 2 * (1 - s) * s * cy + s * s * B.y;
      const id = addNode({ id: `${tag}${i}`, kind: kinds[i - 1] || 'decorative', x: Math.round(x * 10) / 10, y: Math.round(y * 10) / 10 });
      link(prev, id); prev = id;
    }
    link(prev, toId);
  };
  const nearestPort = (ports, target) => {
    const T = byId[target];
    const pref = (id) => (byId[id].kind === 'decorative' ? 40 : 0);
    return ports.slice().sort((a, b) => (Math.hypot(byId[a].x - T.x, byId[a].y - T.y) + pref(a)) - (Math.hypot(byId[b].x - T.x, byId[b].y - T.y) + pref(b)))[0];
  };
  const site = (o) => sites.push({ claimed: false, cubes: 0, pop: 0, step: 0, startStep: 0, ...o });

  addNode({ id: 'high', kind: 'orbit', x: PLACE.high[0], y: PLACE.high[1], label: 'System edge (arrival)' });
  const clusters = []; // { key, depth, ports }

  // ---- companions: the Jupiter cluster, giant at the hub, moons around it
  chits.comps.forEach((cmp, ci) => {
    const pfx = `g${ci}_`; const at = PLACE[`gas${ci}`];
    const c = place('jupiter', pfx, at, cmp.kind === 'white' ? 0.8 : 1);
    const giant = `${short} ${String.fromCharCode(98 + ci)}`;
    display.push({ id: `${pfx}body`, kind: cmp.kind, name: cmp.kind === 'gas' ? giant : `${short} ${cmp.kind === 'brown' ? 'brown' : 'white'} dwarf`, x: at[0], y: at[1] });
    // the skim point: the giant's central Lagrange point (AA-G13)
    const centre = c.ids.filter((id) => byId[id].kind === 'lagrange').sort((a, b) => Math.hypot(byId[a].x - at[0], byId[a].y - at[1]) - Math.hypot(byId[b].x - at[0], byId[b].y - at[1]))[0];
    if (centre) { byId[centre].body = cmp.kind; byId[centre].label = `${display[display.length - 1].name} (Lagrange)`; }
    // Galilean moons become this giant's moons; the outer moonlets are mines
    const moonOrder = ['io', 'europa', 'ganymede', 'callisto'];
    for (const id of c.ids) {
      const n = byId[id]; if (!n.solName) continue;
      const solBody = n.solName.toLowerCase().split(':')[0].trim();
      const mi = moonOrder.indexOf(solBody);
      if (mi >= 0) {
        const body = `${giant}-${ROMAN[mi]}`;
        const ocean = solBody === 'europa' && cmp.chit === 'Ocean';
        const regIdx = sites.filter((s) => s.body === body).length;
        site({ id, node: id, kind: ocean ? 'ocean' : 'moon', body, solBody, name: `${body}: ${GALILEAN[solBody][regIdx] || 'surface'}`, cls: 'Hostile', size: ocean ? rint(5, 7) : rint(3, 6), hyd: ocean ? rint(7, 9) : rint(0, 4), spec: ocean ? 'C' : SPEC[rint(0, 3)], terra: false, primary: regIdx === 0 });
      } else {
        site({ id, node: id, kind: 'mine', body: `${giant} moonlet ${n.solName.charAt(0)}`, name: `${giant} moonlet ${String.fromCharCode(65 + sites.filter((s) => s.kind === 'mine' && s.body.startsWith(giant)).length)}`, cls: null, size: rint(2, 4), hyd: rint(0, 2), spec: SPEC[rint(0, 3)] });
      }
    }
    clusters.push({ key: `gas${ci}`, depth: 1, ports: c.ports });
  });

  // ---- the asteroid belt: the Ceres neighbourhood
  {
    const c = place('ceres', 'b_', PLACE.belt);
    let k = 0;
    for (const id of c.ids) {
      const n = byId[id]; if (!n.solName) continue;
      const big = /ceres/i.test(n.solName);
      site({ id, node: id, kind: 'mine', big, body: `${short} belt ${String.fromCharCode(65 + k)}`, name: `${short} belt ${String.fromCharCode(65 + k)}`, cls: null, size: big ? rint(5, 7) : rint(3, 5), hyd: rint(0, 4), spec: SPEC[rint(0, 3)] });
      k++;
    }
    clusters.push({ key: 'belt', depth: 2, ports: c.ports });
  }

  // ---- the habitable-zone world: the Mars cluster (3 regions + 2 small moons)
  if (chits.hz && chits.hz !== 'None') {
    const c = place('mars', 'h_', PLACE.hz);
    const nm = worldName();
    const [lo, hi] = CLASS_HYD[chits.hz];
    let r = 0, m = 0;
    for (const id of c.ids) {
      const n = byId[id]; if (!n.solName) continue;
      if (/^mars/i.test(n.solName)) {
        site({ id, node: id, kind: 'world', role: 'hz', body: nm, name: `${nm}: ${MARS_REGIONS[r]}`, cls: chits.hz, size: rint(6, 9), hyd: rint(lo, hi), spec: SPEC[rint(0, 3)], terra: true, step: STEP_OF[chits.hz], startStep: STEP_OF[chits.hz], primary: r === 0 });
        r++;
      } else {
        site({ id, node: id, kind: 'mine', body: `${nm} moon ${String.fromCharCode(97 + m)}`, name: `${nm} moon ${String.fromCharCode(97 + m)}`, cls: null, size: rint(2, 4), hyd: rint(0, 2), spec: SPEC[rint(0, 3)] });
        m++;
      }
    }
    clusters.push({ key: 'hz', depth: 3, ports: c.ports, world: nm });
  }

  // ---- the inner rocky world: the Mercury cluster (2 regions)
  {
    const c = place('mercury', 'r_', PLACE.rock);
    const nm = `${star.name} I`; let r = 0;
    for (const id of c.ids) {
      const n = byId[id]; if (!n.solName) continue;
      site({ id, node: id, kind: 'world', role: 'rock', body: nm, name: `${nm}: ${MERCURY_REGIONS[r]}`, cls: 'Hostile', size: rint(4, 6), hyd: rint(0, 1), spec: ['M', 'V'][rint(0, 1)], terra: true, primary: r === 0 });
      r++;
    }
    clusters.push({ key: 'rock', depth: 4, ports: c.ports });
  }

  // ---- wire the gravity well: the edge to the outer clusters, then inward
  const get = (k) => clusters.find((c) => c.key === k);
  const toCluster = (fromId, cl, burns, tag) => chain(fromId, nearestPort(cl.ports, fromId), burns, tag);
  for (const c of clusters.filter((x) => x.key.startsWith('gas'))) toCluster('high', c, 1, `x_${c.key}_`);
  const belt = get('belt'), hz = get('hz'), rock = get('rock');
  toCluster('high', belt, 2, 'x_belt_');
  const innerFrom = hz || belt;
  if (hz) chain(nearestPort(belt.ports, hz.ports[0]), nearestPort(hz.ports, belt.ports[0]), 2, 'x_bh_', -0.15);
  chain(nearestPort(innerFrom.ports, rock.ports[0]), nearestPort(rock.ports, innerFrom.ports[0]), 2, 'x_ir_', 0.2);
  // the giants also reach the inner system directly (as on Sol)
  const g0 = get('gas0');
  if (g0 && hz) chain(nearestPort(g0.ports, hz.ports[0]), nearestPort(hz.ports, g0.ports[0]), 2, 'x_gh_', 0.12);

  // ---- carry a saved system's game state across a relayout, by role
  if (keep && keep.length) {
    const roleOf = (s) => (s.kind === 'world' ? (s.role || (s.id === 'hz' ? 'hz' : 'rock')) : s.kind);
    const pool = sites.slice();
    for (const old of keep) {
      if (!old.claimed && !old.cubes && !old.pop && !(old.step > (old.startStep || 0))) continue;
      const role = roleOf(old);
      const i = pool.findIndex((s) => roleOf(s) === role && (role !== 'world' || s.primary));
      const j = i >= 0 ? i : pool.findIndex((s) => roleOf(s) === role);
      if (j < 0) continue;
      const s = pool.splice(j, 1)[0];
      Object.assign(s, { claimed: !!old.claimed, cubes: old.cubes || 0, pop: old.pop || 0, goo: !!old.goo });
      if (s.terra && old.step != null) for (const t of sites.filter((q) => q.body === s.body)) { t.step = Math.max(t.step, old.step); }
    }
  }
  return { nodes, edges, sites, display, landfall: [], blueprints: [], layout: SYSTEM_LAYOUT };
}
